// NEW (M3) screen builders. Evaluated with K in scope: new Function('K', src)(K) -> S
const {ty,caps,num,ic,a,card,group,lrow,chev,trailTxt,lic,cat,money,txn,btn,chip,seg,field,sw,cb,radio,lin,ring,bars,linec,donut,legend,split,stacked,tooltip,nav,fade,ibtn,hdr,secH,sec,menu,snack,handle,dialog,sheet,body,nphone,F,MONO} = K;
const S = {};
const ph = (t, txt, w, h, o={}) => `<div style="width:${w}px;height:${h}px;border-radius:${o.r??24}px;border:1.5px dashed ${t.olv};display:flex;align-items:center;justify-content:center;text-align:center;padding:12px;box-sizing:border-box;${ty('bS',t.onv)};${o.ex||''}">${txt}</div>`;
S.ph = ph;
const scroll = (inner, o={}) => `<div style="flex:1;overflow:hidden;position:relative"><div style="padding:${o.pt??0}px 20px 0;${o.top?'margin-top:-'+o.top+'px;':''}">${inner}</div></div>`;
S.scroll = scroll;
const pill = (t, txt, bg, fg) => `<span style="${ty('lM',fg,'padding:2px 8px;border-radius:999px;background:'+bg+';white-space:nowrap')}">${txt}</span>`;

// ---------------- Welcome ----------------
const dots = (t, i) => `<div style="display:flex;gap:8px;justify-content:center">${[0,1,2,3].map(j=>`<div style="width:${j===i?24:8}px;height:8px;border-radius:999px;background:${j===i?t.p:t.olv}"></div>`).join('')}</div>`;
const wNav = (t, i, label, o={}) => `<div style="flex:none;padding:12px 20px 24px;display:flex;flex-direction:column;gap:16px">${dots(t,i)}<div style="display:flex;gap:12px">${i===0?'':(i===3?`<div style="width:56px;height:56px;border-radius:999px;border:1px solid ${t.olv};box-sizing:border-box;display:flex;align-items:center;justify-content:center;flex:none">${ic('arrow_back',24,t.on)}</div>`:btn(t,'Back',{kind:'outlined',size:'l',icon:'arrow_back'}))}${btn(t,label,{size:'l',full:1,trail:o.saving?null:'arrow_forward',kind:o.saving?'disabled':'filled'})}</div></div>`;
const skip = (t, show=true) => `<div style="height:56px;flex:none;display:flex;align-items:center;justify-content:flex-end;padding:0 8px">${show?btn(t,'Skip',{kind:'text'}):''}</div>`;
S.welcome = (t, step, o={}) => {
  if (step===0) return skip(t) + `<div style="flex:1;display:flex;flex-direction:column;align-items:center;justify-content:center;padding:0 20px;gap:16px;text-align:center">${ph(t,'OrbitingCoinAnimation 240<br>unchanged painter, orbit dot re-tinted to primary',240,240,{r:999})}
<div style="height:32px;padding:0 12px;border-radius:8px;border:1px solid ${t.olv};display:inline-flex;align-items:center;gap:8px"><span style="width:8px;height:8px;border-radius:999px;background:${t.inc}"></span><span style="${ty('lM',t.onv,'letter-spacing:1px')}">OFFLINE-FIRST · V1.6.0</span></div>
<div style="${ty('hL',t.on)}">Your money.<br>Your rules.</div><div style="${ty('bL',t.onv)}">An expense manager that lives on your device. No cloud, no signup, no compromises.</div></div>` + wNav(t,0,'Get started');
  if (step===1) return skip(t) + `<div style="flex:1;display:flex;flex-direction:column;justify-content:center;padding:0 20px;gap:12px">${ph(t,'Privacy illustration 250×132 (unchanged painter, primary tint)',320,132)}
<div style="${ty('hM',t.on,'margin-top:12px')}">Private by design.</div><div style="${ty('bL',t.onv)}">Your money stays on your device. No telemetry, no syncing, no third parties.</div>
<div style="margin-top:12px">${group(t,[['wifi_off','Fully offline','No cloud servers. Nothing to breach. Works in airplane mode.',1],['no_accounts','No account needed','Open the app and start. Zero signup, zero friction.'],['visibility_off','Privacy mode','One tap hides every balance when you hand over your phone.']].map(([i,h,d,hi])=>`<div style="padding:12px 16px;display:flex;gap:16px;align-items:flex-start"><div style="width:40px;height:40px;border-radius:12px;background:${t.sc};display:flex;align-items:center;justify-content:center;flex:none">${ic(i,20,t.osc)}</div><div><div style="${ty('tM',t.on)}">${h}</div><div style="${ty('bM',t.onv)}">${d}</div></div></div>`))}</div></div>` + wNav(t,1,'Continue');
  if (step===2) { const mods=[['account_balance_wallet','Budgets','p'],['pie_chart','Analytics','s'],['sync','Recurring','t'],['handshake','Lend &amp; borrow','e'],['show_chart','Investments','t'],['auto_awesome','Ask Kuber AI','p'],['calculate','Tools &amp; Calculators','e'],['label','Tags &amp; Categories','p']];
    const tile=(m,w)=>{const [bg,fg]={p:[t.pc,t.opc],s:[t.sc,t.osc],t:[t.tc,t.otc],e:[t.errC,t.onErrC]}[m[2]];return `<div style="background:${t.c2};border:1px solid ${t.olv};border-radius:20px;padding:12px;box-sizing:border-box;display:flex;${w?'align-items:center;gap:12px;':'flex-direction:column;justify-content:space-between;aspect-ratio:1/1;'}"><div style="width:40px;height:40px;border-radius:12px;background:${bg};display:flex;align-items:center;justify-content:center">${ic(m[0],20,fg,1)}</div><div style="${ty('tS',t.on)}">${m[1]}</div></div>`;};
    return skip(t) + `<div style="flex:1;display:flex;flex-direction:column;justify-content:center;padding:0 20px;gap:12px"><div style="${caps(t.onv)}">8+ modules · zero clutter</div><div style="${ty('hM',t.on)}">Everything in<br>one quiet place.</div><div style="${ty('bL',t.onv)}">Track expenses, plan budgets, monitor portfolios, and ask Kuber for answers.</div>
<div style="display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:8px;margin-top:4px">${mods.slice(0,6).map(m=>tile(m)).join('')}</div><div style="display:grid;grid-template-columns:1fr 1fr;gap:8px">${mods.slice(6).map(m=>tile(m,1)).join('')}</div>
<div style="height:48px;border-radius:999px;border:1.5px dashed ${t.p};display:flex;align-items:center;justify-content:center;${ty('lL',t.p)}">••• and much more!</div></div>` + wNav(t,2,'Continue'); }
  // step 3 form
  const nameF = o.error ? field(t,{label:'Your name',value:'',error:'Please enter your name',count:'0/15'}) : field(t,{label:'Your name',value:o.name??'Gaurav',count:`${(o.name??'Gaurav').length}/15`,support:' ',focus:o.focus});
  const pickRow=(mono,h,s)=>lrow(t,{lead:`<div style="width:40px;height:40px;border-radius:999px;background:${t.c3};display:flex;align-items:center;justify-content:center;${ty('tL',t.p)}">${mono}</div>`,title:h,sub:s,trail:ic('search',24,t.onv)});
  return skip(t,false) + `<div style="flex:1;display:flex;flex-direction:column;justify-content:center;padding:0 20px;gap:12px"><div style="${ty('hM',t.on)}">Make it yours.</div><div style="${ty('bL',t.onv,'margin-bottom:12px')}">Three quick choices and you're in.</div>
${nameF}<div>${secH(t,'Language and currency')}${group(t,[pickRow('E','English','English'),pickRow('₹','Indian Rupee','INR · 🇮🇳')])}</div>
<div>${secH(t,'Theme')}<div style="display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:8px">${[['Light',0],['Dark',1],['System',2]].map(([l,m],j)=>{ const on=j===2; const L=K.T('signature_light'), D=K.T('signature_dark'); const mini=(P)=>`<div style="flex:1;background:${P.bg};padding:6px;display:flex;flex-direction:column;gap:4px"><div style="height:6px;width:60%;border-radius:999px;background:${P.on};opacity:.7"></div><div style="height:14px;border-radius:4px;background:${P.c3}"></div><div style="height:6px;width:40%;border-radius:999px;background:${P.p}"></div></div>`; return `<div style="display:flex;flex-direction:column;gap:8px;align-items:center"><div style="width:100%;height:76px;border-radius:16px;overflow:hidden;display:flex;box-sizing:border-box;${on?'box-shadow:0 0 0 2px '+t.bg+',0 0 0 4px '+t.p+';':'border:1px solid '+t.olv+';'}">${m===0?mini(L):m===1?mini(D):mini(L)+mini(D)}</div><div style="display:flex;align-items:center;gap:4px">${on?ic('check_circle',16,t.p,1):''}<span style="${ty('lL',on?t.on:t.onv)}">${l}</span></div></div>`; }).join('')}</div></div></div>` + wNav(t,3,o.saving?'Starting...':'Start my journey',{saving:o.saving});
};

// ---------------- Home widgets ----------------
const W = {};
W.balance = (t, o={}) => o.loading ? card(t,`<div style="width:120px;height:12px;border-radius:999px;background:${t.c3}"></div><div style="width:160px;height:28px;border-radius:999px;background:${t.c3};margin:10px 0 16px"></div><div style="height:8px;border-radius:999px;background:${t.c3}"></div><div style="display:flex;justify-content:space-between;margin-top:12px"><div style="width:72px;height:12px;border-radius:999px;background:${t.c3}"></div><div style="width:72px;height:12px;border-radius:999px;background:${t.c3}"></div></div>`,{pad:20})
 : card(t, `<div style="${caps(t.onv)}">${o.month||'July'} · Net</div><div style="${ty('hM',o.private?t.on:(o.empty?t.onv:t.inc),num+'margin:4px 0 16px')}">${o.private?'****':o.empty?'₹0':'+₹45,200'}</div>${o.empty?`<div style="height:8px;border-radius:999px;background:${t.c4}"></div>`:split(t,.77,t.inc,t.exp)}<div style="display:flex;justify-content:space-between;margin-top:12px"><span style="display:flex;align-items:center;gap:8px;${ty('tS',t.on,num)}"><span style="width:8px;height:8px;border-radius:999px;background:${t.inc}"></span>${o.private?'****':o.empty?'₹0':'₹65,000'}</span><span style="display:flex;align-items:center;gap:8px;${ty('tS',t.on,num)}">${o.private?'****':o.empty?'₹0':'₹19,800'}<span style="width:8px;height:8px;border-radius:999px;background:${t.exp}"></span></span></div>`,{pad:20});
const help = (t) => ic('help',18,t.onv);
const sh = (t, title, right='') => secH(t, `<span style="display:inline-flex;align-items:center;gap:6px">${title}${right.help?help(t):''}${right.beta?pill(t,'Beta',t.sc,t.osc):''}</span>`, right.txt?`<span style="${ty('lL',t.p)}">${right.txt}</span>`:(right.raw||''));
W.stories = (t, o={}) => `<div>${sh(t,'Money stories',{help:1})}${o.empty?card(t,`<div style="${ty('bM',t.onv,'text-align:center')}">Keep spending to see your money stories soon.</div>`):`<div style="display:flex;gap:16px;overflow:hidden">${[['calendar_today','Daily',1],['bar_chart','Weekly',1],['calendar_month','Monthly',0],['auto_awesome','Insights',1],['savings','Yearly',0]].map(([i,l,n])=>`<div style="width:56px;display:flex;flex-direction:column;align-items:center;gap:8px;flex:none">${ring(t,1,56,'normal',{w:3,label:`<div style="width:44px;height:44px;border-radius:999px;background:${t.c3};display:flex;align-items:center;justify-content:center">${ic(i,22,n?t.p:t.onv)}</div>`}).replace(t.p, n?t.p:t.olv)}<span style="${ty('lM',t.on)}">${l}</span></div>`).join('')}</div>`}</div>`;
W.stats = (t) => `<div>${sh(t,'Spending pattern')}${card(t,`<div style="display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:12px">${[['Avg daily','₹1,389','last 90 days'],['This month','₹19,800','5 days'],['Projected','₹43,071','end of month']].map(([l,v,s])=>`<div><div style="${ty('bS',t.onv)}">${l}</div><div style="${ty('tM',t.on,num)}">${v}</div><div style="${ty('bS',t.onv)}">${s}</div></div>`).join('')}</div>`)}</div>`;
W.quick = (t, o={}) => `<div>${sh(t,'Quick add',{help:1,beta:1,raw:`<span style="${ty('lL',t.p)}">Full screen</span>`})}<div style="display:flex;gap:8px;align-items:center"><div style="flex:1;min-width:0;height:56px;border-radius:999px;background:${t.c3};display:flex;align-items:center;padding:0 4px 0 20px;${o.error?'box-shadow:inset 0 0 0 2px '+t.err:''}"><span style="flex:1;${ty('bL',o.value?t.on:t.onv,'white-space:nowrap;overflow:hidden;text-overflow:ellipsis')}">${o.value||'e.g. 250 on groceries from HDFC'}</span>${ibtn(t,'mic',{kind:'std',fg:t.onv})}</div><div style="width:56px;height:56px;border-radius:999px;background:${o.value?t.p:t.c3};display:flex;align-items:center;justify-content:center;flex:none">${o.saving?`<div style="width:20px;height:20px;border-radius:999px;border:2.5px solid ${t.op};border-right-color:transparent;box-sizing:border-box"></div>`:ic('send',22,o.value?t.op:t.onv)}</div></div>${o.error?`<div style="${ty('bS',t.err,'padding:4px 20px 0')}">Enter a valid amount (e.g. 200 on coffee)</div>`:''}</div>`;
W.ask = (t) => `<div>${sh(t,'Ask Kuber')}${card(t,`<div style="height:48px;border-radius:999px;background:${t.c3};display:flex;align-items:center;gap:12px;padding:0 8px 0 16px">${ic('currency_rupee',20,t.p)}<span style="flex:1;${ty('bL',t.onv)}">Ask about your money</span>${ibtn(t,'arrow_forward',{kind:'filled',s:36,g:18})}</div><div style="display:flex;gap:8px;margin-top:12px;overflow:hidden">${[['currency_rupee','This month so far'],['bar_chart','Top category'],['account_balance_wallet','Net worth']].map(([i,l])=>chip(t,l,{icon:i})).join('')}</div>`,{pad:12})}</div>`;
W.sms = (t, o={}) => o.permission ? `<div>${sh(t,'SMS import')}${card(t,`<div style="display:flex;gap:16px"><div style="width:40px;height:40px;border-radius:12px;background:${t.sc};display:flex;align-items:center;justify-content:center;flex:none">${ic('sms',20,t.osc)}</div><div style="flex:1"><div style="${ty('tM',t.on)}">Import from bank SMS</div><div style="${ty('bM',t.onv)}">Let Kuber read bank messages on this device to find transactions.</div></div></div><div style="margin-top:12px;display:flex;justify-content:flex-end">${btn(t,'Allow access',{kind:'tonal',trail:'arrow_forward'})}</div>`)}</div>`
 : `<div>${sh(t,'SMS import')}${group(t,[lrow(t,{lead:`<div style="width:40px;height:40px;border-radius:12px;background:${t.sc};display:flex;align-items:center;justify-content:center;flex:none">${ic('sms',20,t.osc)}</div>`,title:'12 transactions to review',sub:'Last checked 13m ago',trail:chev(t)})])}</div>`;
W.accounts = (t) => `<div>${sh(t,'Accounts',{txt:'View all'})}<div style="display:flex;gap:12px;overflow:hidden">${[['#3B82F6','account_balance','HDFC Bank','Bank','Available','₹82,410'],['#A855F7','credit_card','ICICI Amazon Pay','Credit Card','Outstanding','₹18,400',.18],['#22C55E','payments','Cash','Cash','Available','₹2,140']].map(([c,i,n,ty_,l,v,u])=>card(t,`<div style="display:flex;gap:12px;align-items:center">${cat(t,c,i,{s:36,g:20})}<div style="min-width:0"><div style="${ty('tS',t.on,'white-space:nowrap;overflow:hidden;text-overflow:ellipsis')}">${n}</div><div style="${ty('bS',t.onv)}">${ty_}</div></div></div><div style="${ty('bS',t.onv,'margin-top:16px')}">${l}</div><div style="${ty('tL',t.on,num)}">${v}</div>${u?`<div style="margin-top:8px">${lin(t,u)}</div><div style="display:flex;justify-content:space-between;margin-top:4px;${ty('lS',t.onv,num)}"><span>18% used</span><span>₹1,00,000 limit</span></div>`:''}`,{ex:'width:200px;flex:none'})).join('')}</div></div>`;
W.chart = (t, o={}) => `<div>${sh(t,'Income &amp; expense')}${card(t, o.empty?`<div style="${ty('bM',t.onv,'text-align:center;padding:16px 0')}">No income or expense transactions in the last 7 days. Add a transaction to see your spending analysis here.<br><br>Note: Transfers are not included.</div>`:`<div style="position:relative"><div style="display:flex;justify-content:space-between;align-items:center">${chip(t,'6M',{drop:1,sel:o.menu})}${seg(t,['Bar','Line'],o.line?1:0,{check:false})}</div>${o.menu?`<div style="position:absolute;left:0;top:40px;z-index:2">${menu(t,[{l:'7D',s:'Last 7 days'},{l:'4W',s:'Last 4 weeks'},{l:'6M',s:'Last 6 months',sel:1}],{w:184})}</div>`:''}</div><div style="height:16px"></div>${o.line?linec(t,[{c:t.inc,v:[52,65,0,65,65,65],area:true},{c:t.exp,v:[31,48,24,40,41,18]}],['Apr','May','Jun','Jul','Aug','Sep'],{w:286,h:110,max:67,ticks:['0','33.5K','67K']}):bars(t,[{l:'Apr',v:[52,31]},{l:'May',v:[65,48]},{l:'Jun',v:[0,24]},{l:'Jul',v:[65,40]},{l:'Aug',v:[65,41]},{l:'Sep',v:[65,18]}],{w:286,h:110,colors:[t.inc,t.exp],max:67,ticks:['0','33.5K','67K'],bw:8})}<div style="height:12px"></div>${legend(t,[[t.inc,'Income'],[t.exp,'Expense']])}`)}</div>`;
W.budget = (t) => `<div>${sh(t,'Budget snapshot')}${group(t,[['#EF4444','restaurant','Dining','₹6,200 of ₹8,000','₹1,800 remaining',.42,'normal','On track'],['#F97316','shopping_bag','Shopping','₹4,410 of ₹5,000','₹590 remaining',.88,'near','Near limit'],['#22C55E','local_grocery_store','Groceries','₹9,320 of ₹8,000','₹0 remaining',1,'over','Exceeded']].map(([c,i,n,s,r,v,st,lb])=>`<div style="padding:12px 16px;display:flex;flex-direction:column;gap:10px"><div style="display:flex;gap:16px;align-items:center">${cat(t,c,i)}<div style="flex:1;min-width:0"><div style="${ty('tM',t.on)}">${n}</div><div style="${ty('bM',t.onv,num)}">${s} · ${r}</div></div>${pill(t,lb,st==='over'?t.expC:st==='near'?t.warnC:t.sc,st==='over'?t.onExpC:st==='near'?t.onWarnC:t.osc)}</div>${lin(t,v,st)}</div>`))}</div>`;
W.events = (t, o={}) => `<div>${sh(t,'Upcoming events',{raw:`<span style="${ty('bS',t.onv)}">Next 30 days · 3</span>`})}${o.empty?card(t,`<div style="display:flex;flex-direction:column;align-items:center;gap:8px;padding:8px 0">${ic('calendar_month',24,t.onv)}<div style="${ty('bM',t.onv,'text-align:center')}">Nothing due in the next 30 days.</div></div>`):group(t,[['SEP','12','Home loan EMI','EMI · HDFC Bank','₹24,500','#A855F7'],['SEP','15','Netflix','Recurring · Credit Card','₹649',null],['SEP','20','Rahul owes you','Ledger','₹1,200','#EAB308']].map(([m,d,n,s,v,c])=>lrow(t,{lead:`<div style="width:40px;text-align:center;flex:none"><div style="${ty('lS',t.onv)}">${m}</div><div style="${ty('tM',t.on,num)}">${d}</div></div>`,title:n,sub:s,trail:`<span style="${ty('tS',t.on,num)}">${v}</span>`})))}</div>`;
W.notes = (t, o={}) => `<div>${sh(t,'Kuber notes',{raw:`<span style="${ty('bS',t.onv)}">4 notes</span>`})}${card(t,`<div style="display:flex;gap:16px">${`<div style="width:40px;height:40px;border-radius:12px;background:${t.sc};display:flex;align-items:center;justify-content:center;flex:none">${ic('sticky_note_2',20,t.osc)}</div>`}<div style="min-width:0"><div style="${ty('bS',t.onv)}">Edited today</div><div style="${ty('tM',t.on)}">Goa trip split</div><div style="${ty('bM',t.onv,'white-space:nowrap;overflow:hidden;text-overflow:ellipsis')}">Hotel 12,400 + cab 2,100 = 14,500 / 4</div></div></div><div style="display:flex;gap:8px;margin-top:16px">${btn(t,'View all',{kind:'outlined',icon:'visibility',full:1})}${btn(t,'New note',{kind:'tonal',icon:'add',full:1})}</div>`)}</div>`;
W.recent = (t, o={}) => `<div>${sh(t,'Recent transactions',{txt:'View all'})}${o.empty?card(t,`<div style="${ty('bM',t.onv,'text-align:center;padding:8px 0')}">No transactions yet</div>`):group(t,[txn(t,{c:'#EF4444',i:'restaurant',name:'Tea/Coffee',sub:'Dining · Cash',type:'expense',amt:'80',time:'1:05 PM'}),txn(t,{c:'#64748B',i:'local_gas_station',name:'Cab / Fuel',sub:'Fuel · Credit Card',type:'expense',amt:'984',time:'2:05 AM'}),txn(t,{c:'#22C55E',i:'home',name:'Rent Payment',sub:'Rent · Bank',type:'expense',amt:'18,000',time:'12:00 AM'})])}</div>`;
W.insights = (t, o={}) => `<div>${sh(t,'Smart insights')}${card(t, o.empty?`<div style="display:flex;flex-direction:column;align-items:center;gap:8px">${ic('insights',24,t.onv)}<div style="${ty('bM',t.onv,'text-align:center')}">Keep adding transactions to unlock insights about your finances.</div></div>`:`<div style="display:flex;gap:16px">${`<div style="width:40px;height:40px;border-radius:12px;background:${t.warnC};display:flex;align-items:center;justify-content:center;flex:none">${ic('trending_up',20,t.onWarnC)}</div>`}<div><div style="${ty('tM',t.on)}">Dining is up 24%</div><div style="${ty('bM',t.onv)}">You spent ₹1,200 more on dining than last month.</div></div></div><div style="display:flex;gap:6px;justify-content:center;margin-top:12px">${[1,0,0].map(x=>`<span style="width:${x?16:6}px;height:6px;border-radius:999px;background:${x?t.p:t.olv}"></span>`).join('')}</div>`)}</div>`;
W.edit = (t) => btn(t,'Edit widgets',{kind:'outlined',icon:'tune',full:1});
S.W = W;
const proPill = (t, st) => { const lbl = st==='pro'?'PRO':st==='trial'?'TRIAL · 5d':'Kuber Pro'; return `<div style="height:32px;padding:0 12px 0 8px;border-radius:999px;background:${t.pc};display:inline-flex;align-items:center;gap:6px;vertical-align:middle">${ic('workspace_premium',18,t.opc,1)}<span style="${ty('lL',t.opc,'white-space:nowrap'+(st?';letter-spacing:.8px':''))}">${lbl}</span></div>`; };
S.proPill = proPill;
S.homeHeader = (t, o={}) => hdr(t,{title:proPill(t,o.pro),acts:[ibtn(t,o.private?'visibility_off':'visibility',{kind:o.private?'tonal':undefined}),ibtn(t,'notifications',{badge:o.badge??'3',kind:o.notif?'tonal':undefined})]});
S.tip = (t, txt, right, top=78) => `<div style="position:absolute;top:${top}px;right:${right}px;z-index:3;padding:4px 8px;border-radius:4px;background:${t.inv};${ty('bS',t.oninv,'white-space:nowrap')}">${txt}</div>`;
S.greeting = (t, o={}) => `<div style="margin-bottom:-12px"><div style="${ty('hS',t.on)}">Evening, Gaurav</div><div style="${ty('bM',t.onv,'margin-top:2px')}">${o.sub??'Stay on top of your finances'}</div></div>`;
S.homeOrder = ['stories','stats','quick','ask','sms','accounts','chart','budget','events','notes','recent'];
S.home = (t, o={}) => { const parts = o.loading ? [S.greeting(t,o), W.balance(t,{loading:1}), ...[88,120,88].map(h=>`<div style="height:${h}px;border-radius:20px;background:${t.c2};border:1px solid ${t.olv}"></div>`)] : [S.greeting(t,o), W.balance(t,o), ...(o.only||S.homeOrder).map(k=>W[k](t,o)), W.edit(t)];
  return S.homeHeader(t,o) + `<div style="flex:1;overflow:hidden;position:relative"><div style="padding:0 20px 120px;display:flex;flex-direction:column;gap:28px;${o.top?'margin-top:-'+o.top+'px':''}">${parts.join('')}</div></div>` + fade(t) + nav(t,0); };
S.editWidgets = (t, o={}) => hdr(t,{back:1,close:1,title:'Edit Home Widgets'}) + `<div style="flex:1;overflow:hidden;padding:0 20px"><div style="${ty('bM',t.onv,'margin:0 0 12px')}">Drag the handle to reorder. Toggle to show or hide.</div>${group(t,[['Balance Card','Current-month net with income / expense split',1],['Money Stories','Recaps and highlights about your money',1],['Spending Stats','Spent vs received this month',1],['Quick Add','One-tap expense / income / transfer entry',1],['Ask Kuber','Ask about your money, plus one-tap suggestions',1],['SMS Import','Pending bank SMS transactions to review',o.dirty?0:1],['Bank Accounts','All accounts and balances',1],['Income &amp; Expense','Monthly income vs expense for the last 6 months',1]].map(([n,d,on])=>lrow(t,{lead:ic('drag_indicator',24,t.onv),title:n,sub:d,trail:sw(t,!!on)})))}</div><div style="flex:none;padding:16px 20px 24px;background:${t.bg};border-top:1px solid ${t.olv}">${btn(t,'Save changes',{size:'l',full:1,kind:o.dirty?'filled':'disabled'})}</div>`;

// ---------------- Transaction view sheet ----------------
const infoRows = (t, rows) => group(t, rows.map(([k,v,i,c,tap])=>`<div style="min-height:52px;padding:8px 16px;display:flex;align-items:center;gap:16px;box-sizing:border-box"><span style="${ty('bM',t.onv)}">${k}</span><span style="flex:1;display:flex;justify-content:flex-end;align-items:center;gap:8px;${ty('tS',tap?t.p:t.on,'text-align:right')}">${i?ic(i,18,c||t.onv,1):''}${v}${tap?ic('chevron_right',18,t.p):''}</span></div>`));
S.infoRows = infoRows;
const block = (t, l, inner) => `<div>${secH(t,l)}${inner}</div>`;
S.txnSheet = (t, kind='expense') => { const K_ = {
  expense:{title:'Tea/Coffee',sub:'Expense',lead:cat(t,'#EF4444','restaurant',{s:48,g:24}),amt:money(t,'expense','80','hM'),rows:[['Date &amp; Time','Today • 1:05 PM'],['Account','Cash','payments',t.tone('#22C55E').fg],['Category','Dining','restaurant',t.tone('#EF4444').fg],['Source','Entered by you','edit',t.onv]],extra: block(t,'Notes',`<div style="${ty('bL',t.on)}">Filter coffee with the team after standup.</div>`)+block(t,'Attached tags',`<div style="display:flex;gap:8px">${chip(t,'#trip',{icon:'sell'})}${chip(t,'#work',{icon:'sell'})}</div>`)+block(t,'Attachments',`<div style="display:flex;gap:8px">${ph(t,'IMG',64,64,{r:12})}<div style="width:64px;height:64px;border-radius:12px;background:${t.c3};display:flex;align-items:center;justify-content:center">${ic('picture_as_pdf',28,t.err)}</div></div>`)},
  income:{title:'Salary',sub:'Income',lead:cat(t,'#22C55E','work',{s:48,g:24}),amt:money(t,'income','65,000','hM'),rows:[['Date &amp; Time','Thu, 3 Sep • 9:00 AM'],['Account','HDFC Bank •••• 4321','account_balance',t.tone('#3B82F6').fg],['Category','Salary','work',t.tone('#22C55E').fg],['Source','SMS import','sms',t.onv]],extra: block(t,'Original SMS',`<div style="padding:12px 16px;border-radius:12px;background:${t.c3};font:400 12px/19px ${MONO};color:${t.onv}">Rs.65000.00 credited to A/c XX4321 on 03-09-26 by NEFT SALARY ACME LTD. Avl Bal Rs.82410.50 -HDFC Bank</div>`)},
  transfer:{title:'HDFC Bank → Cash',sub:'Transfer',lead:`<div style="width:48px;height:48px;border-radius:999px;background:${t.c3};display:flex;align-items:center;justify-content:center;flex:none">${ic('swap_horiz',24,t.onv)}</div>`,amt:money(t,'transfer','2,000','hM'),rows:[['Date &amp; Time','Yesterday • 8:40 AM'],['Account','HDFC Bank','account_balance',t.tone('#3B82F6').fg],['Category','Transfer','swap_horiz',t.onv],['Source','Entered by you','edit',t.onv]],extra:''},
  notes:{title:'Groceries',sub:'Expense',lead:cat(t,'#10B981','local_grocery_store',{s:48,g:24}),amt:money(t,'expense','1,240','hM'),rows:[['Date &amp; Time','Today • 6:10 PM'],['Account','Cash','payments',t.tone('#22C55E').fg],['Category','Groceries','local_grocery_store',t.tone('#10B981').fg],['Source','Added from Kuber Notes','sticky_note_2',t.p,1]],extra: btn(t,'View note: "Weekly list"',{kind:'outlined',icon:'sticky_note_2',full:1})+block(t,'Added using prompt',`<div style="${ty('bL',t.on)}">1240 groceries cash</div>`)}
 }[kind];
 return sheet(t,{lead:K_.lead,sub:K_.sub,title:K_.title,mh:700,body:`<div><div style="${caps(t.onv)}">Transaction amount</div><div style="margin-top:4px">${K_.amt}</div></div>${infoRows(t,K_.rows)}${K_.extra}`,gap:20,actions:btn(t,'Edit',{kind:'tonal',icon:'edit',size:'l',full:1})+btn(t,'Delete',{kind:'dangerTonal',icon:'delete',size:'l',full:1})}); };

// ---------------- Add transaction ----------------
const tile2 = (t, l, v, lead, o={}) => `<div style="flex:1;min-width:0;background:${t.c2};border:1px solid ${o.err?t.err:t.olv};border-radius:20px;padding:12px;display:flex;flex-direction:column;gap:8px"><span style="${ty('bS',o.err?t.err:t.onv)}">${l}</span><div style="display:flex;align-items:center;gap:12px">${lead}<span style="${ty('tM',v==='Select'?t.onv:t.on,'white-space:nowrap;overflow:hidden;text-overflow:ellipsis')}">${v}</span></div></div>`;
const amountBlock = (t, v, type) => `<div style="display:flex;align-items:center;gap:8px;padding:8px 0"><span style="${ty('tL',t.onv)}">₹</span><span style="flex:1;text-align:center;${ty('dS',v==='0'?t.onv:(type==='income'?t.inc:type==='expense'?t.exp:t.on),num)}">${v}</span>${ibtn(t,'calculate')}</div><div style="display:flex;gap:8px;justify-content:center">${['+50','+100','+500','+1000'].map(x=>chip(t,x)).join('')}</div>`;
const navRow = (t, i, l, v, o={}) => lrow(t,{lead:`<div style="width:40px;height:40px;border-radius:12px;background:${t.sc};display:flex;align-items:center;justify-content:center;flex:none">${ic(i,20,t.osc)}</div>`,title:v,sub:l,trail:chev(t),...o});
S.add = (t, o={}) => { const type=o.type||'expense'; const isT=type==='transfer';
  const fields = isT ? `${o.subtype?`<div style="${ty('lL',t.onWarnC,'text-align:center;padding:8px 12px;border-radius:12px;background:'+t.warnC)}">Credit card payment</div>`:''}${amountBlock(t,o.amt||'2,000','transfer')}
<div style="display:flex;flex-direction:column;align-items:center;gap:0">${group(t,[lrow(t,{lead:cat(t,'#3B82F6','account_balance'),sub:'From account',title:'HDFC Bank',trail:ic('expand_more',24,t.onv)}),lrow(t,{lead:cat(t,'#A855F7','credit_card'),sub:'To account',title:o.subtype?'ICICI Amazon Pay':'Select Account',trail:ic('expand_more',24,t.onv)})]).replace('overflow:hidden','overflow:visible;width:100%')}</div>`
  : `${field(t,{label:'Transaction name',value:o.name??'',ph:o.name?undefined:'Transaction name',lead:'edit',focus:o.focus})}${o.suggest?`<div style="margin-top:-12px">${menu(t,[{i:'shopping_basket',l:'Weekly Groceries',s:'Groceries · ₹627'},{i:'shopping_basket',l:'Grocery top-up',s:'Groceries · ₹180'}],{w:320})}</div>`:''}
${amountBlock(t,o.amt||'0',type)}
<div style="display:flex;gap:12px">${tile2(t,'Category',o.cat?'Groceries':'Select',o.cat?cat(t,'#10B981','local_grocery_store',{s:36,g:20}):`<div style="width:36px;height:36px;border-radius:12px;background:${t.c3};display:flex;align-items:center;justify-content:center">${ic('category',20,t.onv)}</div>`,{err:o.errCat})}${tile2(t,'From account',o.acc?'Cash':'Select',o.acc?cat(t,'#22C55E','payments',{s:36,g:20}):`<div style="width:36px;height:36px;border-radius:12px;background:${t.c3};display:flex;align-items:center;justify-content:center">${ic('account_balance_wallet',20,t.onv)}</div>`)}</div>
${o.cat?`<div style="padding:12px 16px;border-radius:16px;background:${t.c3};display:flex;flex-direction:column;gap:8px"><div style="display:flex;justify-content:space-between;${ty('bS',t.onv,num)}"><span style="display:flex;gap:6px;align-items:center">${ic('account_balance_wallet',16,t.p)}Budget</span><span>₹6,920 / ₹8,000 · 86% used</span></div>${lin(t,.86,'near')}</div>`:''}`;
  return hdr(t,{back:1,close:1,title:o.edit?'Edit Transaction':'Add Transaction',acts:o.edit?[]:[ibtn(t,'more_vert')]}) + `<div style="flex:1;overflow:hidden;position:relative"><div style="padding:4px 20px 24px;display:flex;flex-direction:column;gap:16px;${o.top?'margin-top:-'+o.top+'px':''}">
${K.ptabs(t,['Expense','Income','Transfer'],['expense','income','transfer'].indexOf(type))}${fields}
${group(t,[navRow(t,'calendar_today','Date &amp; time','Today • 11:15 PM'),navRow(t,'sell','Tags',o.tags?'2 tags selected':'No tags selected',{third:o.tags?`<div style="display:flex;gap:6px;margin-top:6px">${chip(t,'#trip')}${chip(t,'#family')}</div>`:'',h:o.tags?104:72}),navRow(t,'attach_file','Attachments','Add image or PDF')])}
${field(t,{ph:'Add a note (optional)',lead:'notes'})}
${o.edit?'':btn(t,'Save &amp; Add Another',{kind:'outlined',size:'l',full:1})}</div></div>
<div style="flex:none;padding:12px 20px 24px;background:${t.bg};border-top:1px solid ${t.olv}">${btn(t,o.edit?'Update Expense':isT?'Save Transfer':type==='income'?'Save Income':'Save Expense',{size:'l',full:1})}</div>${o.snack?`<div style="position:absolute;left:20px;right:20px;top:40px">${snack(t,{msg:o.snack,variant:'error',p:.8})}</div>`:''}`; };
S.calc = (t) => sheet(t,{title:'Calculator',mh:640,body:`<div style="padding:8px 4px;text-align:right"><div style="${ty('bL',t.onv,num)}">1,240 + 380 × 2</div><div style="display:flex;justify-content:flex-end;align-items:baseline;gap:4px"><span style="${ty('tL',t.onv)}">₹</span><span style="${ty('dS',t.on,num)}">2,000</span></div></div>
<div style="display:grid;grid-template-columns:repeat(4,1fr);gap:8px">${['C','%','⌫','÷','7','8','9','×','4','5','6','−','1','2','3','+','.','0','=',''].slice(0,19).map((k,i)=>{const op='÷×−+='.includes(k), fn='C%⌫'.includes(k);return `<div style="height:56px;border-radius:999px;${k==='='?'grid-column:span 2;':''}background:${op?t.sc:fn?t.c4:t.c3};display:flex;align-items:center;justify-content:center;${ty('tL',op?t.osc:t.on)}">${k==='⌫'?ic('backspace',22,t.on):k}</div>`;}).join('')}</div>`,actions:btn(t,'Use ₹2,000',{size:'l',full:1,icon:'check'})});
S.catPicker = (t) => { const cs=[['#EF4444','restaurant','Dining'],['#10B981','local_grocery_store','Groceries',1],['#64748B','local_gas_station','Fuel'],['#22C55E','home','Rent'],['#F97316','shopping_bag','Shopping'],['#D946EF','checkroom','Clothing'],['#0EA5E9','flight','Travel'],['#F59E0B','bolt','Utilities']];
  const grid=(arr)=>`<div style="display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:12px 8px">${arr.map(([c,i,n,sel,b])=>`<div style="display:flex;flex-direction:column;align-items:center;gap:6px;position:relative"><div style="width:56px;height:56px;border-radius:16px;background:${t.tone(c).cont};display:flex;align-items:center;justify-content:center;${sel?'box-shadow:0 0 0 2px '+t.bg+',0 0 0 4px '+t.p+';':''}">${ic(i,26,t.tone(c).fg,1)}</div><span style="${ty('lM',t.on,'text-align:center')}">${n}</span>${b?pill(t,'Budget',t.sc,t.osc):''}</div>`).join('')}</div>`;
  return sheet(t,{title:'Select Category',mh:640,body:`${field(t,{lead:'search',ph:'Search categories'})}<div>${secH(t,'Food')}${grid([cs[0],[...cs[1],1],cs[2],cs[3]].map((x,i)=>i===0?[...x,0,1]:x))}</div><div>${secH(t,'Ungrouped')}${grid(cs.slice(4))}</div>`,actions:btn(t,'Add new category',{kind:'outlined',icon:'add',size:'l',full:1})}); };
S.accPicker = (t) => sheet(t,{title:'Select Account',sub2:'Choose the account for this transaction',mh:560,body:`${field(t,{lead:'search',ph:'Search accounts...'})}${group(t,[['#3B82F6','account_balance','HDFC Bank','Bank','₹82,410'],['#22C55E','payments','Cash','Cash','₹2,140',1],['#A855F7','credit_card','ICICI Amazon Pay','Credit Card','−₹18,400'],['#F59E0B','account_balance_wallet','Paytm Wallet','Wallet','₹310']].map(([c,i,n,s,v,sel])=>lrow(t,{lead:cat(t,c,i),title:n,sub:s,sel,trail:`<span style="${ty('tS',sel?t.osc:t.on,num)}">${v}</span>${sel?ic('check_circle',20,t.osc,1):''}`})))}`,actions:btn(t,'Add new account',{kind:'outlined',icon:'add',size:'l',full:1})});
S.attachSheet = (t) => sheet(t,{title:'Add Attachments',sub2:'Max 5MB per file',mh:300,body:`<div style="display:grid;grid-template-columns:repeat(3,1fr);gap:12px">${[['photo_camera','Camera'],['photo_library','Gallery'],['picture_as_pdf','PDF']].map(([i,l])=>`<div style="height:96px;border-radius:20px;background:${t.c2};border:1px solid ${t.olv};display:flex;flex-direction:column;align-items:center;justify-content:center;gap:8px"><div style="width:40px;height:40px;border-radius:12px;background:${t.sc};display:flex;align-items:center;justify-content:center">${ic(i,20,t.osc)}</div><span style="${ty('lL',t.on)}">${l}</span></div>`).join('')}</div>`});

// ---------------- History ----------------
const filterRow = (t, o={}) => { const active = o.inc||o.exp||o.adv||o.active;
 if (o.search) return `<div style="height:48px;border-radius:999px;background:${t.c2};border:2px solid ${t.p};box-sizing:border-box;display:flex;align-items:center;padding:0 2px">${ibtn(t,'arrow_back',{kind:'std'})}<span style="flex:1;min-width:0;${ty('bL',t.on)}">rent<span style="display:inline-block;width:2px;height:20px;background:${t.p};vertical-align:-4px;margin-left:1px"></span></span>${ibtn(t,'close',{kind:'std',fg:t.onv})}</div>`;
 return `<div style="display:flex;flex-direction:column;gap:8px"><div style="display:flex;gap:8px;align-items:center">${chip(t,'Exp',{sel:o.exp})}${chip(t,'Inc',{sel:o.inc})}<span style="flex:1"></span><div style="display:flex;margin-right:-4px">${active?ibtn(t,'filter_alt_off',{kind:'danger'}):''}${ibtn(t,'search')}${ibtn(t,'tune',{kind:o.adv?'tonal':undefined,badge:o.adv?'2':'',bc:t.p,bfc:t.op})}</div></div>${o.adv?`<div style="display:flex;gap:8px;flex-wrap:wrap">${chip(t,'Dining',{sel:1,x:1})}${chip(t,'HDFC Bank',{sel:1,x:1})}</div>`:''}</div>`; };
const selSum = (t) => `<div style="position:absolute;left:0;right:0;bottom:22px;display:flex;justify-content:center;z-index:2"><div style="height:48px;padding:0 20px;border-radius:999px;background:${t.inv};display:flex;align-items:center;gap:16px;${ty('lM',t.oninv,num+'white-space:nowrap')}"><span>EXP <span style="font-weight:700;color:${K.T(t.dark?'signature_light':'signature_dark').exp}">−₹1,464</span></span><span>INC <span style="font-weight:700">₹0</span></span><span>NET <span style="font-weight:700;color:${K.T(t.dark?'signature_light':'signature_dark').exp}">−₹1,464</span></span></div></div>`;
S.filterRow = filterRow;
const summary = (t, o={}) => `<div style="display:flex;gap:12px;white-space:nowrap;${ty('lM',t.onv,num)}"><span>EXP <span style="color:${t.exp}">−₹${o.e||'1,32,434'}</span></span><span>INC <span style="color:${t.inc}">+₹${o.i||'1,95,000'}</span></span><span>NET <span style="color:${t.inc}">+₹${o.n||'62,566'}</span></span></div><div style="${ty('bS',t.onv,'margin-top:4px')}">Showing <span style="color:${t.p};font-weight:600">${o.c||'172'}</span> transactions</div>`;
const day = (t, label, total, rows) => `<div>${secH(t,label,`<span style="${ty('lL',t.onv,num)}">${total}</span>`)}${group(t,rows)}</div>`;
S.histList = (t, sel) => [day(t,'Today','−₹19,464',[txn(t,{c:'#EF4444',i:'restaurant',name:'Tea/Coffee',sub:'Dining · Cash',tag:'#trip',type:'expense',amt:'80',time:'1:05 PM',sel:sel&&sel.includes(0)}),txn(t,{c:'#64748B',i:'local_gas_station',name:'Cab / Fuel',sub:'Fuel · Credit Card',type:'expense',amt:'984',time:'2:05 AM',sel:sel&&sel.includes(1)}),txn(t,{c:'#EF4444',i:'restaurant',name:'Lunch / Dinner',sub:'Dining · Cash',tag:'#trip',type:'expense',amt:'400',time:'12:34 AM',sel:sel&&sel.includes(2)}),txn(t,{c:'#22C55E',i:'home',name:'Rent Payment',sub:'Rent · Bank',type:'expense',amt:'18,000',time:'12:00 AM',sel:sel&&sel.includes(3)})]),day(t,'Thu, 3 Sep','+₹64,920',[txn(t,{c:'#22C55E',i:'work',name:'Salary',sub:'Salary · HDFC Bank',type:'income',amt:'65,000',time:'9:00 AM'}),txn(t,{c:'#EF4444',i:'restaurant',name:'Tea/Coffee',sub:'Dining · Cash',type:'expense',amt:'80',time:'8:15 AM'})])].join('');
S.history = (t, o={}) => { const sel=o.sel;
  const head = sel ? hdr(t,{back:1,close:1,title:`${sel.length} selected`,bgc:t.c2,acts:[ibtn(t,'select_all'),ibtn(t,'delete',{kind:'danger'})]}) : hdr(t,{title:'Transactions',acts:[ibtn(t,'more_vert',{kind:o.menu?'tonal':undefined})]});
  let content;
  if (o.loading) content = `${filterRow(t)}<div style="height:36px;border-radius:999px;background:${t.c2};width:70%"></div>${[0,1].map(()=>`<div><div style="width:80px;height:12px;border-radius:999px;background:${t.c3};margin-bottom:12px"></div>${group(t,[0,1,2].map(()=>`<div style="height:72px;padding:0 16px;display:flex;align-items:center;gap:16px"><div style="width:40px;height:40px;border-radius:12px;background:${t.c3}"></div><div style="flex:1"><div style="width:60%;height:12px;border-radius:999px;background:${t.c3}"></div><div style="width:40%;height:10px;border-radius:999px;background:${t.c3};margin-top:8px"></div></div><div style="width:56px;height:12px;border-radius:999px;background:${t.c3}"></div></div>`))}</div>`).join('')}`;
  else if (o.empty) content = `${filterRow(t,o.filtered?{inc:1,active:1}:{})}<div style="padding-top:16px">${o.filtered?summary(t,{e:'0',i:'0',n:'0',c:'0'}):''}</div><div style="display:flex;flex-direction:column;align-items:center;text-align:center;gap:12px;padding:48px 12px 0"><div style="width:72px;height:72px;border-radius:999px;background:${t.sc};display:flex;align-items:center;justify-content:center">${ic('receipt_long',32,t.osc)}</div><div style="${ty('tM',t.on)}">${o.filtered?'No transactions found':'No transactions yet'}</div><div style="${ty('bM',t.onv)}">${o.filtered?'Try adjusting your search or filters':'Start tracking your expenses'}</div>${o.filtered?btn(t,'Clear filters',{kind:'text'}):btn(t,'Add Transaction',{icon:'add'})}</div>`;
  else content = `${sel?'':filterRow(t,o.f||{})}${sel?'':`<div>${summary(t,o.f&&o.f.search?{e:'54,000',i:'0',n:'−54,000',c:'3'}:{})}</div>`}${o.f&&o.f.search?day(t,'This month','−₹18,000',[txn(t,{c:'#22C55E',i:'home',name:'Rent Payment',sub:'Rent · Bank',type:'expense',amt:'18,000',time:'1 Sep'})]):S.histList(t,sel)}`;
  return head + `<div style="flex:1;overflow:hidden;position:relative"><div style="padding:4px 20px 120px;display:flex;flex-direction:column;gap:${sel?20:20}px">${content}</div></div>` + (sel?fade(t)+selSum(t):fade(t)+nav(t,1)) + (o.menu?`<div style="position:absolute;top:96px;right:16px;z-index:3">${menu(t,[{i:'file_download',l:'Export',s:'CSV, PDF or JSON'}],{w:220})}</div>`:'') + (o.dialog?dialog(t,{title:'Delete 3 transactions?',body:'This action cannot be undone.',actions:btn(t,'Cancel',{kind:'text'})+btn(t,'Delete',{kind:'danger'})}):'') + (o.snack?`<div style="position:absolute;left:20px;right:20px;top:40px">${snack(t,{msg:o.snack,act:o.snackAct,p:.7})}</div>`:''); };

// ---------------- Analytics ----------------
const acard = (t, title, sub, inner, o={}) => card(t, `<div style="display:flex;align-items:flex-start;gap:12px;margin-bottom:16px"><div style="flex:1;min-width:0"><div style="${ty('tM',t.on)}">${title}</div>${sub?`<div style="${ty('bM',t.onv)}">${sub}</div>`:''}${o.under||''}</div>${o.act||''}</div>${o.tabs?o.tabs+'<div style="height:16px"></div>':''}${inner}`);
const A = {};
A.filter = (t) => `<div style="display:flex;gap:8px;align-items:center;min-width:0">${chip(t,'All',{sel:1,drop:1})}${chip(t,'Jun 8 - Sep 5',{icon:'calendar_today',ic:t.onv,shrink:1})}<span style="flex:1"></span>${ibtn(t,'restart_alt')}</div>`;
A.summary = (t) => card(t, `<div style="display:grid;grid-template-columns:1fr 1fr;gap:12px">${[['south','Income','₹1,95,000',t.inc],['north','Expense','₹1,32,434',t.exp]].map(([i,l,v,c])=>`<div style="padding:12px;border-radius:12px;background:${t.c3}"><div style="display:flex;gap:4px;align-items:center;${ty('bS',t.onv)}">${ic(i,16,c)}${l}</div><div style="${ty('tL',t.on,num)}">${v}</div></div>`).join('')}</div><div style="display:flex;justify-content:space-between;align-items:center;margin-top:12px;padding:12px;border-radius:12px;background:${t.c3}"><span style="${ty('bM',t.onv)}">Net</span><span style="${ty('tL',t.inc,num)}">+₹62,566</span></div>`);
A.trend = (t, o={}) => acard(t,'Income &amp; Expense','',o.line?linec(t,[{c:t.inc,v:[0,65,65,65],area:true},{c:t.exp,v:[24,40,41,18]}],['Jun','Jul','Aug','Sep'],{w:286,h:130,max:67,ticks:['0','33.5K','67K']}):bars(t,[{l:'Jun',v:[0,24]},{l:'Jul',v:[65,40]},{l:'Aug',v:[65,41]},{l:'Sep',v:[65,18]}],{w:286,h:130,colors:[t.inc,t.exp],max:67,ticks:['0','33.5K','67K']}),{act:seg(t,['Bar','Line'],o.line?1:0,{check:false}),under:`<div style="margin-top:8px">${chip(t,'Month',{drop:1})}</div>`}) .replace(/<\/div>$/, `<div style="height:12px"></div>${legend(t,[[t.inc,'Income'],[t.exp,'Expense']])}</div>`);
A.heat = (t) => acard(t,'Avg Weekly Heatmap','Based on your selected filter',`<div style="display:flex;gap:6px">${['MON','TUE','WED','THU','FRI','SAT','SUN'].map((d,i)=>`<div style="flex:1;display:flex;flex-direction:column;gap:6px;align-items:center"><div style="width:100%;height:40px;border-radius:8px;background:${t.heat[[2,1,3,1,1,3,4][i]]};${i===6?'box-shadow:inset 0 0 0 2px '+t.on+';':''}"></div><span style="${ty('lS',i===6?t.on:t.onv)}">${d}</span></div>`).join('')}</div><div style="display:flex;justify-content:space-between;align-items:center;margin:16px 0 8px"><span style="${caps(t.onv)}">Intensity</span><div style="display:flex;gap:4px">${t.heat.map(c=>`<span style="width:12px;height:12px;border-radius:4px;background:${c}"></span>`).join('')}</div></div>${group(t,[['Monday','₹542.92'],['Tuesday','₹374.13'],['Wednesday','₹1,226.96'],['Thursday','₹354.19'],['Friday','₹376.86'],['Saturday','₹1,071.54'],['Sunday','₹1,434.77',1]].map(([d,v,s])=>`<div style="height:44px;padding:0 16px;display:flex;align-items:center;justify-content:space-between;${s?'background:'+t.sc+';':''}"><span style="${ty('bM',s?t.osc:t.on)}">${d}</span><span style="${ty('tS',s?t.osc:t.on,num)}">${v}</span></div>`))}`);
A.size = (t) => acard(t,'Transaction Size Distribution','Frequency by ticket size',`${stacked(t,[[54,t.heat[4]],[41,t.heat[2]],[5,t.heat[1]]])}<div style="display:flex;flex-direction:column;gap:12px;margin-top:16px">${[[t.heat[4],'Small (&lt;₹500)','54%'],[t.heat[2],'Medium (₹500 - ₹2,000)','41%'],[t.heat[1],'Large (&gt;₹2,000)','5%']].map(([c,l,v])=>`<div style="display:flex;align-items:center;gap:12px"><span style="width:8px;height:8px;border-radius:999px;background:${c}"></span><span style="flex:1;${ty('bM',t.on)}">${l}</span><span style="${ty('tS',t.on,num)}">${v}</span></div>`).join('')}</div>`,{act:ibtn(t,'tune')});
A.donut = (t) => { const sl=[['#22C55E','Rent','40.8%','₹54,000'],['#EF4444','Dining','23.5%','₹31,120'],['#10B981','Groceries','14%','₹18,504'],['#64748B','Fuel','12.1%','₹16,000'],['#D946EF','Clothing','5.3%','₹7,050'],['#F59E0B','Utilities','4.3%','₹5,760']];
  return acard(t,'Spending by category','',`<div style="display:flex;justify-content:center">${donut(t,sl.map(([c,,p])=>({c:t.tone(c).viz,v:parseFloat(p)})),{center:`<div style="${ty('tL',t.on,num)}">₹1,32,434</div><div style="${ty('bS',t.onv)}">6 categories</div>`})}</div><div style="height:16px"></div>${group(t,sl.map(([c,n,p,v])=>`<div style="height:48px;padding:0 16px;display:flex;align-items:center;gap:12px"><span style="width:10px;height:10px;border-radius:999px;background:${t.tone(c).viz}"></span><span style="flex:1;${ty('bM',t.on)}">${n}</span><span style="${ty('bS',t.onv,num)}">${p}</span><span style="width:76px;text-align:right;${ty('tS',t.on,num)}">${v}</span></div>`))}`,{act:chip(t,'Category',{drop:1})}); };
A.tags = (t) => acard(t,'Tag-wise Analytics','Spending by tag',`<div style="display:flex;flex-direction:column;gap:16px">${[['#trip','36.6%','₹9,839',.366],['#family','30.1%','₹8,106',.301],['#work','18.9%','₹5,075',.189],['#personal','14.5%','₹3,895',.145]].map(([n,p,v,x])=>`<div style="display:flex;flex-direction:column;gap:8px"><div style="display:flex;align-items:center;gap:8px"><span style="${ty('tS',t.on)}">${n}</span><span style="${ty('bS',t.onv,num)}">${p}</span><span style="flex:1"></span><span style="${ty('tS',t.on,num)}">${v}</span></div>${lin(t,x)}</div>`).join('')}</div><div style="margin-top:20px">${secH(t,'Top tags contribution')}<div style="display:grid;grid-template-columns:repeat(3,1fr);gap:8px">${[['#trip','22'],['#personal','13'],['#family','12']].map(([n,c])=>`<div style="padding:12px;border-radius:12px;background:${t.c3};text-align:center"><div style="${ty('bS',t.onv)}">${n}</div><div style="${ty('hS',t.on,num)}">${c}</div><div style="${ty('bS',t.onv)}">txns</div></div>`).join('')}</div></div>`,{act:ic('sell',20,t.onv)});
A.biggest = (t) => acard(t,'Biggest Transactions','',group(t,[1,2,3].map(i=>lrow(t,{lead:`<span style="width:24px;${ty('lL',t.onv,num)}">#${i}</span>`+cat(t,'#22C55E','home'),title:'Rent Payment',sub:'Rent · '+['1 Sep','1 Aug','1 Jul'][i-1],trail:money(t,'expense','18,000')}))),{tabs:seg(t,['Expense','Income'],0)});
A.teaser = (t) => group(t,[lrow(t,{lead:`<div style="width:40px;height:40px;border-radius:12px;background:${t.pc};display:flex;align-items:center;justify-content:center;flex:none">${ic('insert_chart',20,t.opc)}</div>`,title:`View deeper insights ${pill(t,'Pro',t.sc,t.osc)}`,sub:'Trends, patterns, forecast, health score',trail:chev(t)})]);
S.A = A;
S.analytics = (t, o={}) => { const parts = o.empty ? [A.filter(t), `<div style="display:flex;flex-direction:column;align-items:center;text-align:center;gap:12px;padding:56px 12px 0"><div style="width:72px;height:72px;border-radius:999px;background:${t.sc};display:flex;align-items:center;justify-content:center">${ic('insert_chart',32,t.osc)}</div><div style="${ty('tM',t.on)}">No data</div><div style="${ty('bM',t.onv)}">No transactions found for this period</div></div>`] : [A.filter(t), A.summary(t), A.trend(t,o), A.heat(t), A.size(t), A.donut(t), A.tags(t), A.biggest(t), A.teaser(t), btn(t,'Edit widgets',{kind:'outlined',icon:'tune',full:1})];
  return hdr(t,{title:'Analytics'}) + `<div style="flex:1;overflow:hidden;position:relative"><div style="padding:4px 20px 120px;display:flex;flex-direction:column;gap:12px;${o.top?'margin-top:-'+o.top+'px':''}">${parts.join('')}</div></div>` + fade(t) + nav(t,2); };
S.advanced = (t) => hdr(t,{back:1,home:1,acts:[ibtn(t,'help')]}) + `<div style="flex:1;overflow:hidden;padding:0 20px;display:flex;flex-direction:column;gap:12px"><div><div style="${ty('tL',t.on)}">Advanced Analytics</div><div style="${ty('bM',t.onv)}">Deep analysis of your financial patterns</div></div>
${card(t,`<div style="display:flex;gap:16px;align-items:center">${ring(t,.98,56,'normal',{label:`<span style="${ty('tM',t.on,num)}">98</span>`})}<div style="flex:1"><div style="${ty('tM',t.on)}">Financial health score</div><div style="${ty('bM',t.onv)}"><span style="color:${t.inc};font-weight:600">Good</span> · finances are in great shape</div></div>${chev(t)}</div>`)}
${group(t,[['bar_chart','Year over year','+0.0% vs last year'],['category','Category deep-dive','Merchants, trends and weekday habits'],['donut_large','Spending patterns','You spend most on Sundays, mostly in the morning'],['trending_up','Forecast','Likely to spend ₹18,766 by month end'],['account_balance_wallet','Cash flow','Variable · 32% savings rate'],['track_changes','Anomaly detection','5 unusual patterns noticed this month']].map(([i,h,s])=>lrow(t,{lead:lic(t,i,t.p),title:h,sub:s,trail:chev(t)})))}</div>`;

// ---------------- More ----------------
S.more = (t, o={}) => { const R=(i,h,s,tr)=>lrow(t,{lead:lic(t,i),title:h,sub:s,trail:(tr||'')+chev(t)});
  const parts = [
   card(t,`<div style="display:flex;gap:16px;align-items:center"><div style="width:40px;height:40px;border-radius:12px;background:${t.pc};display:flex;align-items:center;justify-content:center;flex:none">${ic('workspace_premium',22,t.opc,1)}</div><div style="flex:1"><div style="${ty('tM',t.on)}">Kuber Pro</div><div style="${ty('bM',t.onv)}">MorePremiumHeroCard slot (Pro round)</div></div>${chev(t)}</div>`),
   `<div>${secH(t,'Manage')}${group(t,[R('account_balance_wallet','Accounts','Your wallets and bank accounts',trailTxt(t,'4')),R('category','Categories','Organize your transactions'),R('label','Tags','Organize the labels for your transactions'),R('pie_chart','Budgets','Track and control your monthly spending'),R('sync','Recurring Transactions','Automated scheduled transactions'),R('handshake','Lend / Borrow','Track money you lent or borrowed'),R('account_balance','Loans','Track EMIs and repayment progress'),R('show_chart','Investments','Track portfolio value and growth')])}</div>`,
   `<div>${secH(t,'Signature')}${group(t,[R('auto_awesome','Ask Kuber','On-device smart assistant',pill(t,'Beta',t.sc,t.osc)),R('sms','Import from SMS','Read bank SMS for transactions'),R('insert_chart','Advanced Analytics','Deep analytical views of your finances'),R('calculate','Calculators &amp; Tools','EMI, SIP, salary, GST, split &amp; more'),R('sticky_note_2','Kuber Notes','Jot expenses and do quick math'),R('credit_card','Kuber Cards','Encrypted vault to save all your cards'),R('bolt','Quick Add','Type or speak to log transactions',pill(t,'Beta',t.sc,t.osc)),R('notifications_active','Reminders','Never miss anything money-related')])}</div>`,
   `<div>${secH(t,'App')}${group(t,[R('settings','Settings','Theme, currency, and profile'),R('storage','Data','Export, import, automatic backups'),R('notifications','Notifications','Recent alerts and reminders'),R('calendar_month','Upcoming Events','Everything coming up, in one place'),R('auto_stories','Money Stories Archive','Every recap, newest first'),R('widgets','Widgets','Home screen widgets to keep Kuber in view')])}</div>`,
   `<div>${secH(t,'Tutorial')}${group(t,[lrow(t,{lead:lic(t,'school'),title:'App Tutorial',trail:pill(t,'Beta',t.sc,t.osc)+chev(t)}),lrow(t,{lead:lic(t,'auto_stories'),title:'Welcome Tour',trail:chev(t)})])}</div>`,
   `<div>${secH(t,'About')}${group(t,[lrow(t,{lead:lic(t,'info'),title:'About Kuber',trail:chev(t)}),lrow(t,{lead:lic(t,'security'),title:'Permissions',trail:chev(t)})])}</div>`,
   `<div>${secH(t,'Help us',`<span style="${ty('bS',t.onv)}">Tap to support</span>`)}<div style="display:grid;grid-template-columns:repeat(3,1fr);gap:8px">${[['star','Rate Kuber',1],['share','Share'],['feedback','Feedback']].map(([i,l,w])=>`<div style="height:88px;border-radius:20px;background:${t.c2};border:1px solid ${t.olv};display:flex;flex-direction:column;align-items:center;justify-content:center;gap:8px"><div style="width:40px;height:40px;border-radius:12px;background:${w?t.warnC:t.sc};display:flex;align-items:center;justify-content:center">${ic(i,20,w?t.onWarnC:t.osc,1)}</div><span style="${ty('lL',t.on)}">${l}</span></div>`).join('')}</div><div style="margin-top:12px">${btn(t,'Buy me a coffee',{kind:'tonal',icon:'local_cafe',full:1})}</div></div>`,
   `<div style="text-align:center;${ty('bS',t.onv)}">Made with <span style="color:${t.exp}">♥</span> in India · v1.6.0</div>`];
  return hdr(t,{title:'More',acts:[ibtn(t,'search'),ibtn(t,'more_vert',{kind:o.menu?'tonal':undefined})]}) + `<div style="flex:1;overflow:hidden;position:relative"><div style="padding:4px 20px 120px;display:flex;flex-direction:column;gap:28px;${o.top?'margin-top:-'+o.top+'px':''}">${parts.join('')}</div></div>` + fade(t) + nav(t,3); };
return S;
